// Illustrative: an adapter's work is a call into an application that knows no streams, which a marble example could only fake; this is the shape the app's command feature gives it.
// the adapter listens on the channel for load
loaded$ = events.on(load).pipe(
  // a newer load cancels the call still in flight
  switchMap(() =>
    // the adapter calls the application through its own interface
    defer(() => boardApi.load()).pipe(
      // the application's reply becomes a message on the channel
      map((document) => loadSuccess(document)),
      // and so does its failure
      catchError((error) => of(loadFailure(toAppError(error)))),
    ),
  ),
);
